-- Create "usage_hourlies" table
CREATE TABLE "usage_hourlies" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" bigint NOT NULL, "bucket_at" timestamptz NOT NULL, "user_id" bigint NOT NULL, "department_id" bigint NOT NULL DEFAULT 0, "model_id" bigint NOT NULL, "agent_id" bigint NOT NULL DEFAULT 0, "calls" bigint NOT NULL DEFAULT 0, "error_calls" bigint NOT NULL DEFAULT 0, "prompt_tokens" bigint NOT NULL DEFAULT 0, "cached_tokens" bigint NOT NULL DEFAULT 0, "completion_tokens" bigint NOT NULL DEFAULT 0, "reasoning_tokens" bigint NOT NULL DEFAULT 0, "total_tokens" bigint NOT NULL DEFAULT 0, "cost_micros" bigint NOT NULL DEFAULT 0, "estimated_calls" bigint NOT NULL DEFAULT 0, "estimated_tokens" bigint NOT NULL DEFAULT 0, "estimated_cost_micros" bigint NOT NULL DEFAULT 0, "unknown_calls" bigint NOT NULL DEFAULT 0, "updated_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "usagehourly_org_id_agent_id_bucket_at" to table: "usage_hourlies"
CREATE INDEX "usagehourly_org_id_agent_id_bucket_at" ON "usage_hourlies" ("org_id", "agent_id", "bucket_at");
-- Create index "usagehourly_org_id_bucket_at" to table: "usage_hourlies"
CREATE INDEX "usagehourly_org_id_bucket_at" ON "usage_hourlies" ("org_id", "bucket_at");
-- Create index "usagehourly_org_id_bucket_at_u_2a6e68416d50575cfb2b8f256458374a" to table: "usage_hourlies"
CREATE UNIQUE INDEX "usagehourly_org_id_bucket_at_u_2a6e68416d50575cfb2b8f256458374a" ON "usage_hourlies" ("org_id", "bucket_at", "user_id", "department_id", "model_id", "agent_id");
-- Create index "usagehourly_org_id_department_id_bucket_at" to table: "usage_hourlies"
CREATE INDEX "usagehourly_org_id_department_id_bucket_at" ON "usage_hourlies" ("org_id", "department_id", "bucket_at");
-- Create index "usagehourly_org_id_model_id_bucket_at" to table: "usage_hourlies"
CREATE INDEX "usagehourly_org_id_model_id_bucket_at" ON "usage_hourlies" ("org_id", "model_id", "bucket_at");
